Interface MedioDePago
  Method Cobrar(monto As Integer) As Integer;
EndInterface

Class Efectivo Implements MedioDePago
  Method Cobrar(monto As Integer) As Integer
    Return monto;
  EndMethod
EndClass

Class Tarjeta Implements MedioDePago
  Method Cobrar(monto As Integer) As Integer
    Return monto + monto * 5 Div 100;
  EndMethod
EndClass

Subroutine CobrarCon<T: MedioDePago>(medio As T, monto As Integer) As Integer
  Return medio.Cobrar(monto);
EndSubroutine

Class Producto
  Define nombre As String;
  Define precio As Integer;

  Method Constructor(n As String, p As Integer)
    This.nombre <- n;
    This.precio <- p;
  EndMethod

  Method Importe(cantidad As Integer) As Integer
    Return This.precio * cantidad;
  EndMethod
EndClass

Class Inventario
  Private Define stock As Vector<Integer>;

  Method Constructor()
    This.stock <- vector();
    This.stock.append(10);
    This.stock.append(5);
    This.stock.append(8);
    This.stock.append(12);
    This.stock.append(6);
  EndMethod

  Method Queda(codigo As Integer) As Integer
    Return This.stock[codigo - 1];
  EndMethod

  Method Quitar(codigo As Integer, cantidad As Integer) As Boolean
    If cantidad > This.stock[codigo - 1] Then
      Return False;
    EndIf
    This.stock[codigo - 1] <- This.stock[codigo - 1] - cantidad;
    Return True;
  EndMethod
EndClass

Class Caja
  Private Define total As Integer;

  Method Constructor()
    This.total <- 0;
  EndMethod

  Method Sumar(importe As Integer)
    This.total <- This.total + importe;
  EndMethod

  Method Total() As Integer
    Return This.total;
  EndMethod

  Method ConDescuento() As Integer
    Return This.total - This.total Div 10;
  EndMethod
EndClass

Subroutine Catalogo() As Vector<Producto>
  Define productos As Vector<Producto> <- vector();
  productos.append(New Producto("Jugo", 3));
  productos.append(New Producto("Sándwich", 5));
  productos.append(New Producto("Alfajor", 2));
  productos.append(New Producto("Agua", 1));
  productos.append(New Producto("Fruta", 2));
  Return productos;
EndSubroutine

Algorithm Kiosco
  Define productos As Vector<Producto> <- Catalogo();
  Define inventario As Inventario <- New Inventario();
  Define caja As Caja <- New Caja();
  Define codigo, cantidad As Integer;
  Read codigo;
  While codigo <> 0 Do
    Read cantidad;
    If codigo < 1 Or codigo > 5 Then
      Write "Código ", codigo, " no existe";
    Else
      Define producto As Producto <- productos[codigo - 1];
      If cantidad < 1 Then
        Write "Cantidad ", cantidad, " no válida";
      Else
        If inventario.Quitar(codigo, cantidad) Then
          caja.Sumar(producto.Importe(cantidad));
          Write producto.nombre, " x ", cantidad, " = ", producto.Importe(cantidad);
        Else
          Write producto.nombre, " x ", cantidad, " rechazado: quedan ", inventario.Queda(codigo);
        EndIf
      EndIf
    EndIf
    Read codigo;
  EndWhile
  Define pago As String;
  Read pago;
  Write "Total: ", caja.Total();
  Write "Con descuento: ", caja.ConDescuento();
  If pago = "tarjeta" Then
    Write "A pagar con tarjeta: ", CobrarCon(New Tarjeta(), caja.ConDescuento());
  Else
    Write "A pagar en efectivo: ", CobrarCon(New Efectivo(), caja.ConDescuento());
  EndIf
  Write "Stock final:";
  For i <- 1 To 5 Do
    Write productos[i - 1].nombre, " ", inventario.Queda(i);
  EndFor
EndAlgorithm
